use std::sync::{Arc, Mutex};
use std::thread;

fn t1(a: Arc<Mutex<()>>, b: Arc<Mutex<()>>) {
    let mut tmp: i32 = 0;
    {
        let _a = a.lock().unwrap();
        let _b = b.lock().unwrap();
        tmp = 1;
    }
    let _ = tmp;
}

fn t2(b: Arc<Mutex<()>>, c: Arc<Mutex<()>>) {
    let mut tmp: i32 = 0;
    {
        let _b = b.lock().unwrap();
        let _c = c.lock().unwrap();
        tmp = 1;
    }
    let _ = tmp;
}

fn t3(a: Arc<Mutex<()>>, c: Arc<Mutex<()>>) {
    let mut tmp: i32 = 0;
    {
        let _a = a.lock().unwrap();
        let _c = c.lock().unwrap();
        tmp = 1;
    }
    let _ = tmp;
}

fn main() {
    let a = Arc::new(Mutex::new(()));
    let b = Arc::new(Mutex::new(()));
    let c = Arc::new(Mutex::new(()));

    let a1 = Arc::clone(&a);
    let b1 = Arc::clone(&b);
    let h1 = thread::spawn(move || t1(a1, b1));

    let b2 = Arc::clone(&b);
    let c2 = Arc::clone(&c);
    let h2 = thread::spawn(move || t2(b2, c2));

    let a3 = Arc::clone(&a);
    let c3 = Arc::clone(&c);
    let h3 = thread::spawn(move || t3(a3, c3));

    h1.join().unwrap();
    h2.join().unwrap();
    h3.join().unwrap();

    println!("DONE done=1");
}
