    work = 1;

    drop(gb);
    drop(ga);

    let _ = work;
}

fn w2(a: Arc<Mutex<()>>, b: Arc<Mutex<()>>) {
    let mut work = 0;

    let ga = a.lock().unwrap();
    let gb = b.lock().unwrap();

    work = 1;

    drop(gb);
    drop(ga);

    let _ = work;
}

fn main() {
    let a = Arc::new(Mutex::new(()));
    let b = Arc::new(Mutex::new(()));

